INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_54_m_54_2_52',
  'Which AWS service provides intelligent threat detection to protect AWS accounts and workloads by continuously monitoring for malicious activity and unauthorized behavior?',
  'mcq',
  '["AWS CloudTrail","Amazon GuardDuty","AWS Config","Amazon Macie"]'::json,
  '{1}',
  'Option B (correct) is Amazon GuardDuty, which is a threat detection service that continuously monitors for malicious activity and unauthorized behavior to protect AWS accounts and workloads. It uses machine learning, anomaly detection, and integrated threat intelligence to identify and prioritize potential threats. Option A (incorrect) is AWS CloudTrail, which records API calls and related events in your AWS account, primarily for auditing and governance, not active threat detection. Option C (incorrect) is AWS Config, which assesses, audits, and evaluates the configurations of your AWS resources, helping with compliance and identifying unauthorized configuration changes, but not active threat detection of malicious activity. Option D (incorrect) is Amazon Macie, which focuses on discovering, classifying, and protecting sensitive data in Amazon S3, primarily for PII and data security, not general threat detection for account and workload behavior.',
  NOW(),
  'quiz_domain54_12',
  NOW(),
  31,
  NULL,
  NULL,
  'm_54_2',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_54_m_54_2_53',
  'Which AWS service is designed to aggregate, organize, and prioritize security findings from various AWS services (like Amazon GuardDuty, Amazon Inspector, and Amazon Macie) and third-party security products?',
  'mcq',
  '["AWS CloudTrail","Amazon Security Hub","AWS Config","Amazon EventBridge"]'::json,
  '{1}',
  'Option B (correct) is Amazon Security Hub. It provides a comprehensive view of your security state in AWS and helps you check your compliance with security industry standards and best practices. Security Hub collects security data from across AWS accounts, services, and supported third-party products, and helps you analyze your security trends and identify the highest priority security issues. Option A (incorrect) is AWS CloudTrail, which records API activity and events for auditing and governance. Option C (incorrect) is AWS Config, which assesses, audits, and evaluates the configurations of your AWS resources. Option D (incorrect) is Amazon EventBridge, a serverless event bus service that makes it easier to connect applications together by routing events from AWS services, your own applications, and SaaS applications to targets, but it does not aggregate and prioritize security findings.',
  NOW(),
  'quiz_domain54_12',
  NOW(),
  32,
  NULL,
  NULL,
  'm_54_2',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
