INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_54_m_54_1_62',
  'When responding to a suspected compromise of an IAM user''s access keys, which actions are essential to mitigate ongoing unauthorized access? (Select TWO.)',
  'multiple',
  '["Rotate the compromised IAM access keys.","Delete the IAM user immediately.","Invalidate all active sessions for the compromised IAM user.","Change the IAM user''s password.","Attach an explicit allow policy to the IAM user."]'::json,
  '{0,2}',
  'Option A (Rotate the compromised IAM access keys) deactivates the old, compromised keys and generates new ones, preventing future use of the compromised credentials. Option C (Invalidate all active sessions for the compromised IAM user) is crucial because rotating keys does not automatically invalidate existing AWS STS sessions that were established using the compromised keys. This can be done by using an explicit deny policy based on the time-of-issue. Option B (Delete the IAM user immediately) is too drastic and may hinder forensic investigation or disrupt legitimate operations. Option D (Change the IAM user''s password) is important if the password was also compromised, but doesn''t address active sessions or access keys directly. Option E (Attach an explicit allow policy to the IAM user) would grant more permissions, which is the opposite of what is needed during a compromise.',
  NOW(),
  'quiz_domain54_12',
  NOW(),
  2,
  NULL,
  NULL,
  'm_54_1',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
