INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_54_m_54_2_68',
  'Which AWS services are essential for centralizing security findings and detecting configuration changes? (Select TWO.)',
  'multiple',
  '["Amazon Security Hub","AWS Config","Amazon SQS","AWS Step Functions","Amazon Kinesis"]'::json,
  '{0,1}',
  'Option A (Amazon Security Hub) aggregates security findings from various AWS services (like GuardDuty, Macie, Inspector) and third-party products into a single, normalized view, and checks against security standards. Option B (AWS Config) continuously monitors and records your AWS resource configurations and allows you to automate the evaluation of recorded configurations against desired baselines, detecting unauthorized changes. Option C (Amazon SQS) is a message queuing service. Option D (AWS Step Functions) is for orchestrating workflows. Option E (Amazon Kinesis) is for real-time data streaming. These three are not primarily for centralizing security findings or detecting configuration changes.',
  NOW(),
  'quiz_domain54_12',
  NOW(),
  22,
  NULL,
  NULL,
  'm_54_2',
  'easy'
);

