INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_54_m_54_2_79',
  'Which AWS services can be used to monitor network traffic for anomalies and detect unusual API calls that might indicate a security threat? (Select TWO.)',
  'multiple',
  '["VPC Flow Logs","AWS CloudTrail Insights","Amazon Inspector","AWS Config","Amazon Macie"]'::json,
  '{0,1}',
  'Option A (VPC Flow Logs) captures information about the IP traffic going to and from network interfaces in your VPC, which can be analyzed for network-layer anomaly detection. Option B (AWS CloudTrail Insights) specifically detects unusual API activity by continuously analyzing AWS CloudTrail events for anomalies, such as an unusual number of API calls or calls from unusual locations. Option C (Amazon Inspector) is a vulnerability management service, not for network traffic or API call anomaly detection. Option D (AWS Config) monitors resource configurations, not network traffic or API calls. Option E (Amazon Macie) is for sensitive data discovery in S3, not network or API monitoring.',
  NOW(),
  'quiz_domain54_12',
  NOW(),
  33,
  NULL,
  NULL,
  'm_54_2',
  'medium'
);

