INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_54_m_54_1_96',
  'To perform forensic analysis on a potentially compromised Amazon EC2 instance, a security analyst needs to capture volatile and persistent data. Order the following actions to ensure proper evidence preservation.',
  'ordering',
  '["Create Amazon EBS snapshots of all attached volumes to preserve disk state.","Isolate the EC2 instance by modifying its security groups to block all network traffic.","Capture a memory dump of the EC2 instance to analyze volatile data.","Remove the EC2 instance from any associated load balancers and Auto Scaling groups."]'::json,
  '{3,1,0,2}',
  'According to best practices for EC2 forensics, the first step (Option D) is to remove the instance from load balancers and Auto Scaling groups to prevent further impact on the application. Next, Option B: isolate the instance by modifying its security groups to block all network traffic, preventing further malicious activity or data exfiltration. Then, Option A: create EBS snapshots of all attached volumes to preserve the persistent disk state. Finally, Option C: capture a memory dump of the EC2 instance to analyze volatile data, which would be lost upon termination or reboot. This order ensures evidence is preserved before any destructive actions.',
  NOW(),
  'quiz_domain54_12',
  NOW(),
  15,
  NULL,
  NULL,
  'm_54_1',
  'medium'
);

