INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_54_m_54_1_112',
  'An EC2 instance is suspected of being compromised. A security team needs to perform forensic analysis while minimizing further impact. Order the steps for isolating the instance and preserving evidence.',
  'ordering',
  '["Capture a memory dump from the compromised EC2 instance.","Remove the EC2 instance from any associated load balancers or target groups.","Create Amazon EBS snapshots of all attached volumes.","Modify the security groups and Network ACLs to restrict all inbound and outbound traffic."]'::json,
  '{1,3,2,0}',
  'When an EC2 instance is compromised, the first step is to isolate it to prevent further damage or spread, which involves removing it from load balancers (Option B) and restricting network traffic (Option D). After isolation, preserving evidence is critical, starting with creating Amazon EBS snapshots of all attached volumes (Option C) to capture disk state. Finally, capturing a memory dump (Option A) is crucial for volatile data analysis. Terminating the instance immediately (an anti-pattern) would destroy valuable forensic evidence.',
  NOW(),
  'quiz_domain54_12',
  NOW(),
  31,
  NULL,
  NULL,
  'm_54_1',
  'medium'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
