INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_54_m_54_2_103',
  'A security operations center (SOC) needs a centralized view of security findings from various AWS services. Order the steps to set up Amazon Security Hub for this purpose.',
  'ordering',
