  NOW(),
  39,
  '{"left":["Detect proprietary formats","Identify specific patterns","Exclude known safe data","Scan all objects"],"right":["Custom data identifiers with regex","Custom data identifiers with keywords","Allow lists for specific S3 prefixes","Configure Macie discovery jobs"]}'::json,
  '{"left":[0,1,2,3],"right":[0,1,2,3]}'::jsonb,
  'm_54_2',
  'hard'
);

