INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_56_m_56_3_31',
  'Which AWS service helps scan Amazon EC2 instances and container images for software vulnerabilities and unintended network exposure?',
