INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_56_m_56_3_32',
  'What is the primary benefit of using IMDSv2 over IMDSv1 for Amazon EC2 instances?',
  'mcq',
  '["Provides faster metadata retrieval for applications.","Requires a session token, mitigating Server-Side Request Forgery (SSRF) attacks for credential theft.","Supports more metadata categories for instance configuration.","Allows direct access to IAM roles without requiring explicit permissions."]'::json,
  '{1}',
  'Option B (correct) highlights the key security advantage of IMDSv2. It requires a session token for all requests, making it more resilient against SSRF vulnerabilities that could be exploited to steal temporary IAM credentials. Option A is incorrect; IMDSv2 adds a step, not necessarily faster. Option C and Option D are not primary benefits of IMDSv2''s security enhancements.',
  NOW(),
  'quiz_domain56_12',
  NOW(),
  29,
  NULL,
  NULL,
  'm_56_3',
  'easy'
);

