);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_56_m_56_3_39',
  'Which AWS service is used to scan Amazon EC2 instances and container images for software vulnerabilities and unintended network exposure?',
  'mcq',
  '["AWS Systems Manager Patch Manager","Amazon Inspector","AWS Security Hub","Amazon GuardDuty"]'::json,
  '{1}',
  'Option B (correct) is Amazon Inspector, a vulnerability management service that continuously scans AWS workloads for software vulnerabilities and unintended network exposure. Option A, AWS Systems Manager Patch Manager, automates the patching of operating systems and applications but does not scan for vulnerabilities. Option C, AWS Security Hub, aggregates security findings from various AWS services but does not perform the scanning itself. Option D, Amazon GuardDuty, is a threat detection service that monitors for malicious activity and unauthorized behavior, but not for software vulnerabilities.',
  NOW(),
  'quiz_domain56_12',
