);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_56_m_56_4_38',
  'What information do Amazon VPC Flow Logs primarily capture?',
  'mcq',
  '["Metadata about network traffic, such as source/destination IP, port, protocol, and action (ACCEPT/REJECT).","The content of network packets for deep packet inspection.","Configuration changes made to security groups and NACLs.","Performance metrics for network interfaces within a VPC."]'::json,
  '{0}',
  'Option A (correct) accurately describes what Amazon VPC Flow Logs capture: metadata about IP traffic going to and from network interfaces in your VPC, including source/destination IP addresses, ports, protocols, the number of bytes and packets, and the action (ACCEPT or REJECT). Option B is incorrect; Flow Logs capture metadata, not packet content. Option C is incorrect; configuration changes are typically monitored by AWS Config. Option D is incorrect; performance metrics are typically monitored by Amazon CloudWatch.',
