INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_56_m_56_1_79',
  'Order the steps to deploy AWS WAF to protect an Amazon CloudFront distribution.',
  'ordering',
  '["Add rules to the Web ACL","Associate the Web ACL with the CloudFront distribution","Test the WAF rules","Create a Web ACL"]'::json,
  '{3,0,1,2}',
  'Deploying AWS WAF to protect an Amazon CloudFront distribution follows a logical sequence. Option D (correct) is the initial step, as you must first create a Web ACL, which is the container for your WAF rules. Option A (correct) then involves adding specific rules (e.g., IP match rules, SQL injection rules, managed rule groups) to this Web ACL. Option B (correct) is to associate the configured Web ACL with your CloudFront distribution, making the WAF rules active for traffic flowing through CloudFront. Finally, Option C (correct) is to test the WAF rules to ensure they are blocking malicious traffic as intended without impacting legitimate users.',
  NOW(),
  'quiz_domain56_12',
  NOW(),
  38,
  NULL,
  NULL,
  'm_56_1',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_56_m_56_1_80',
  'Arrange the steps to enable AWS Shield Advanced protection for an Amazon Route 53 hosted zone.',
