  NULL,
  'm_57_1',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_57_m_57_1_112',
  'To enhance security, an organization requires all IAM users to enable Multi-Factor Authentication (MFA). Order the steps an IAM user would typically follow to activate a virtual MFA device.',
  'ordering',
  '["Sign in to the AWS Management Console as the IAM user.","Navigate to the ''Security credentials'' section.","Scan the QR code with a virtual MFA application and enter two consecutive MFA codes.","Choose ''Assign MFA device'' and select ''Virtual MFA device''."]'::json,
  '{0,1,3,2}',
  'The process for an IAM user to activate a virtual MFA device begins with Option A (signing in to the AWS Management Console as the IAM user). Then, the user must Option B (navigate to the ''Security credentials'' section). From there, Option D (choose ''Assign MFA device'' and select ''Virtual MFA device''). Finally, Option C (scan the QR code with a virtual MFA application and enter two consecutive MFA codes) to complete the activation.',
