INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_57_m_57_1_113',
  'An organization wants to continuously monitor for unintended external access to its AWS resources. Order the general workflow steps for using AWS IAM Access Analyzer.',
  'ordering',
  '["Enable IAM Access Analyzer for an AWS Region.","Review the generated findings for external access.","Remediate identified access issues by modifying policies.","Configure archive rules for trusted external entities."]'::json,
  '{0,1,3,2}',
  'The process for using AWS IAM Access Analyzer starts by Option A (enabling IAM Access Analyzer for an AWS Region). Once enabled, it begins analyzing resources, and you then Option B (review the generated findings for external access). To manage legitimate external access, Option D (configure archive rules for trusted external entities) to filter out expected findings. Finally, Option C (remediate identified access issues by modifying policies) for any unintended access.',
  NOW(),
  'quiz_domain57_12',
  NOW(),
