INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_57_m_57_1_124',
  'An administrator uses AWS STS to assume an IAM role, and also specifies a session policy during the `AssumeRole` call. Order the effective policy evaluation flow for actions taken with these temporary credentials, assuming no explicit deny.',
  'ordering',
  '["The identity-based policies attached to the assumed role.","The Service Control Policies (SCPs) from AWS Organizations.","The session policy provided during the `AssumeRole` call.","Any permission boundary attached to the assumed role."]'::json,
  '{1,3,0,2}',
  'When a session policy is used, it acts as an additional filter. The evaluation order is: Option B (Service Control Policies) are evaluated first. Then, Option D (Any permission boundary attached to the assumed role) is evaluated. Next, Option A (The identity-based policies attached to the assumed role) are evaluated. Finally, Option C (The session policy provided during the `AssumeRole` call) is applied, further restricting the effective permissions. The effective permissions are the intersection of all ''allow'' policies at each stage.',
  NOW(),
  'quiz_domain57_12',
  NOW(),
  16,
  NULL,
  NULL,
  'm_57_1',
  'medium'
);

