INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_57_m_57_1_130',
  'A security engineer is tasked with reducing the number of overly permissive IAM policies in an AWS account. Order the steps to effectively use IAM Access Analyzer''s unused access findings to achieve this goal.',
