INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_57_m_57_1_131',
  'A company wants to enforce Multi-Factor Authentication (MFA) for all IAM users performing sensitive API actions. Order the steps to configure and enforce MFA for an IAM user.',
