INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_55_m_55_4_73',
  'A security analyst enabled DNS query logging for Amazon Route 53 Resolver but is not seeing logs in the configured Amazon S3 bucket. Order the steps to diagnose missing DNS query logs.',
  'ordering',
  '["Verify the Amazon S3 bucket policy allows Route 53 Resolver to write logs.","Check the status and configuration of Route 53 Resolver query logging.","Review the IAM permissions for the Route 53 Resolver service.","Examine the Route 53 Resolver configurations for any errors."]'::json,
  '{1,0,2,3}',
  'To diagnose missing DNS query logs from Route 53 Resolver, the initial step is to check the status and configuration of Route 53 Resolver query logging to ensure it is enabled and correctly pointing to the S3 bucket (Option B). Next, verify the Amazon S3 bucket policy to confirm it grants Route 53 Resolver the necessary permissions to write logs (Option A). Following this, review the IAM permissions associated with the Route 53 Resolver service to ensure it has the required access (Option C). Finally, examine the overall Route 53 Resolver configurations for any other potential misconfigurations or errors that might affect log delivery (Option D).',
  NOW(),
  'quiz_domain55_12',
  NOW(),
  87,
  NULL,
  NULL,
  'm_55_4',
  'medium'
);

