INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_55_m_55_2_55',
  'A security engineer needs to update the workflow status of a Security Hub finding after remediation. Order the steps to manage the workflow status.',
  'ordering',
  '["Navigate to the AWS Security Hub console and select ''Findings''.","Locate the specific finding that has been remediated.","Change the ''Workflow status'' of the finding to ''RESOLVED''.","Add a comment to the finding explaining the remediation action taken."]'::json,
  '{0,1,2,3}',
  'To update the workflow status of a Security Hub finding, the first step is to navigate to the AWS Security Hub console and select ''Findings'' (Option A). Next, locate the specific finding that has been remediated (Option B). Then, change the ''Workflow status'' of the finding to ''RESOLVED'' (Option C) to indicate that the issue has been addressed. Finally, add a comment to the finding (Option D) explaining the remediation action taken, which provides an audit trail and context for future reviews.',
