INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_57_m_57_1_147',
  'Match the IAM policy evaluation stage to its characteristic.',
  'matching',
  '{"A":"Explicit Deny","B":"Service Control Policy (SCP)","C":"Identity-based policy"}'::json,
  NULL,
  'An Explicit Deny (left: 0) in any policy always overrides any allow statement (right: 0), ensuring that access is blocked. A Service Control Policy (SCP) (left: 1) acts as an organizational guardrail and is evaluated first in the policy evaluation logic (right: 1), setting maximum permissions for accounts. An Identity-based policy (left: 2) defines the permissions for an IAM principal (user, group, or role) (right: 2) and is evaluated after SCPs and permission boundaries.',
  NOW(),
  'quiz_domain57_12',
  NOW(),
  7,
  '{"left":["Explicit Deny","Service Control Policy (SCP)","Identity-based policy"],"right":["Always overrides allow statements","Organizational guardrail, evaluated first","Defines permissions for an IAM principal"]}'::json,
