INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_56_m_56_1_94',
  'Match each AWS WAF rule type to its primary function.',
  'matching',
  '{"A":"Custom rules","B":"Managed rule groups","C":"Rate-based rules"}'::json,
  NULL,
  'Custom rules allow you to define specific conditions that AWS WAF evaluates for web requests, giving granular control over traffic. Managed rule groups are pre-configured sets of rules provided by AWS or AWS Marketplace sellers to protect against common threats. Rate-based rules automatically block or count requests from IP addresses that exceed a configured threshold within a five-minute period, mitigating DDoS attacks.',
  NOW(),
  'quiz_domain56_12',
