  'm_56_1',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_56_m_56_1_95',
  'Match each Amazon CloudFront security feature to its purpose.',
  'matching',
  '{"A":"HTTPS enforcement","B":"Origin Access Control (OAC)","C":"Security headers"}'::json,
  NULL,
  'HTTPS enforcement ensures that all communication between clients and CloudFront, and optionally between CloudFront and the origin, is encrypted, protecting data in transit. Origin Access Control (OAC) is used to restrict direct access to Amazon S3 buckets, ensuring that content can only be accessed through CloudFront. Security headers, configured through CloudFront functions or Lambda@Edge, can help mitigate common web vulnerabilities like cross-site scripting (XSS) and clickjacking.',
  NOW(),
  'quiz_domain56_12',
  NOW(),
  2,
  '{"left":["HTTPS enforcement","Origin Access Control (OAC)","Security headers"],"right":["Restrict direct access to S3 buckets","Ensure encrypted communication with clients","Mitigate common web vulnerabilities"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_56_1',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
