INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_56_m_56_1_105',
  'Match the CloudFront security feature to its purpose.',
  'matching',
  '{"A":"HTTPS enforcement","B":"Security headers","C":"Origin Access Control (OAC)"}'::json,
  NULL,
  'HTTPS enforcement (Option A) on CloudFront ensures that all data transferred between clients and CloudFront, and between CloudFront and the origin, is encrypted in transit. Configuring security headers (Option B) helps mitigate common web vulnerabilities like XSS and clickjacking. Origin Access Control (OAC) (Option C) is used to securely restrict access to Amazon S3 buckets, ensuring they can only be accessed through CloudFront distributions.',
  NOW(),
  'quiz_domain56_12',
