  12,
  '{"left":["HTTPS enforcement","Security headers","Origin Access Control (OAC)"],"right":["Encrypt data in transit","Mitigate web vulnerabilities","Secure S3 bucket access"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_56_1',
  'medium'
);

