INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_58_m_58_1_30',
  'To ensure that all data uploaded to an Amazon S3 bucket is always encrypted in transit, which protocol should be enforced for all access requests?',
  'mcq',
  '["FTP","HTTP","SMTP","HTTPS"]'::json,
  '{3}',
  'Option D (HTTPS) is the correct protocol to enforce for all access requests to an Amazon S3 bucket to ensure data is encrypted in transit. HTTPS uses TLS/SSL to encrypt communication between the client and S3. Option A (FTP) and Option C (SMTP) are different protocols not typically used for S3 access. Option B (HTTP) transmits data unencrypted, which does not meet the requirement for encryption in transit.',
  NOW(),
  'quiz_domain58_12',
  NOW(),
  31,
  NULL,
  NULL,
  'm_58_1',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_58_m_58_1_31',
  'Which AWS networking service enables you to establish an encrypted connection between your on-premises network and your Amazon VPC over the public internet?',
