INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_58_m_58_1_36',
  'When using AWS Certificate Manager (ACM), what is the process for using certificates issued by a third-party Certificate Authority (CA) with AWS services?',
  'mcq',
  '["ACM automatically requests certificates from third-party CAs.","You must import the third-party certificate into ACM.","Third-party certificates cannot be used with ACM.","ACM acts as a proxy for third-party CA requests."]'::json,
  '{1}',
  'Option B (You must import the third-party certificate into ACM) is the correct process. AWS Certificate Manager allows you to import certificates issued by external third-party Certificate Authorities for use with supported AWS services. Option A is incorrect as ACM issues its own certificates or uses Private CA. Option C is incorrect as importing is a supported feature. Option D is incorrect as ACM does not proxy requests for external CAs.',
  NOW(),
  'quiz_domain58_12',
  NOW(),
