INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_58_m_58_4_33',
  'An application needs to securely store and retrieve API keys for third-party services. Which AWS service is best suited for this purpose, offering encryption and access control?',
