INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_58_m_58_4_34',
  'What is a security best practice for managing credentials in application code to prevent them from being exposed or compromised?',
  'mcq',
  '["Hardcode credentials directly into the application source code.","Store credentials in plain text configuration files.","Retrieve credentials dynamically from a secrets management service.","Embed credentials in environment variables on the application server."]'::json,
  '{2}',
  'Option C (Retrieve credentials dynamically from a secrets management service) is a security best practice. Services like AWS Secrets Manager or AWS Systems Manager Parameter Store allow applications to retrieve credentials at runtime, preventing hardcoding or storing them in plain text. Option A (Hardcoding credentials) and Option B (Storing in plain text files) are severe security anti-patterns. Option D (Embedding in environment variables) is better than hardcoding but still less secure than dynamic retrieval from a dedicated secrets management service.',
  NOW(),
  'quiz_domain58_12',
  NOW(),
  82,
  NULL,
  NULL,
  'm_58_4',
  'easy'
);

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_58_m_58_4_35',
  'Which AWS KMS feature allows you to create cryptographic keys that can be replicated and used in multiple AWS Regions without re-encrypting data?',
