INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_59_m_59_1_47',
  'What do AWS Config rules primarily evaluate?',
  'mcq',
  '["The configuration settings of your AWS resources.","The performance metrics of your applications.","The cost optimization recommendations for your accounts.","The network latency between AWS Regions."]'::json,
  '{0}',
  'Option A (correct) is what AWS Config rules primarily evaluate. AWS Config continuously monitors and records your AWS resource configurations and allows you to automate the evaluation of recorded configurations against desired configurations, defined by AWS Config rules. Option B (Performance metrics) is handled by Amazon CloudWatch. Option C (Cost optimization) is handled by AWS Cost Explorer and AWS Trusted Advisor. Option D (Network latency) is a network performance metric.',
  NOW(),
  'quiz_domain59_12',
  NOW(),
