INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_59_m_59_1_48',
  'A Chief Information Security Officer (CISO) requires a consolidated, high-level overview of the security posture across all organizational AWS accounts and wants to track compliance against security standards. Which AWS service provides this capability?',
  'mcq',
  '["AWS Config","Amazon Security Hub","AWS CloudFormation","AWS Audit Manager"]'::json,
  '{1}',
  'Option B (correct) is Amazon Security Hub. It provides a comprehensive view of your security posture across your AWS accounts and helps you check your environment against security industry standards and best practices. It aggregates findings from various security services into a single dashboard. Option A (AWS Config) assesses individual resource configurations. Option C (AWS CloudFormation) provisions infrastructure. Option D (AWS Audit Manager) collects evidence for audits, but Security Hub provides the consolidated security posture view.',
  NOW(),
  'quiz_domain59_12',
  NOW(),
  20,
  NULL,
  NULL,
  'm_59_1',
