INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_59_m_59_2_46',
  'A security engineer wants to ensure that all new Amazon S3 buckets created in the organization automatically enforce encryption at rest. Which type of control would be most effective to prevent non-compliant S3 buckets from being created?',
